-- market4u isolated namespace: every table and column starts with market_.
create extension if not exists "pgcrypto";
create table if not exists public.market_mercados (market_id uuid primary key default gen_random_uuid(), market_nome text not null, market_criado_em timestamptz not null default now());
create table if not exists public.market_usuarios (market_mercado_id uuid not null references public.market_mercados(market_id) on delete cascade, market_usuario_id uuid not null references auth.users(id) on delete cascade, market_perfil text not null default 'manager', market_criado_em timestamptz not null default now(), primary key (market_mercado_id, market_usuario_id));
create table if not exists public.market_produtos (market_id uuid primary key default gen_random_uuid(), market_mercado_id uuid not null references public.market_mercados(market_id) on delete cascade, market_nome text not null check (char_length(market_nome) between 1 and 160), market_sku text not null, market_categoria text not null, market_quantidade_estoque integer not null default 0 check (market_quantidade_estoque >= 0), market_preco_custo numeric(12,2) not null check (market_preco_custo >= 0), market_preco_venda numeric(12,2) not null check (market_preco_venda >= 0), market_criado_em timestamptz not null default now(), unique (market_mercado_id, market_sku));
create table if not exists public.market_vendas (market_id uuid primary key default gen_random_uuid(), market_mercado_id uuid not null references public.market_mercados(market_id) on delete cascade, market_produto_id uuid not null references public.market_produtos(market_id), market_quantidade integer not null check (market_quantidade > 0), market_preco_custo_unitario numeric(12,2) not null, market_preco_venda_unitario numeric(12,2) not null, market_faturamento numeric(12,2) generated always as (market_quantidade * market_preco_venda_unitario) stored, market_cmv numeric(12,2) generated always as (market_quantidade * market_preco_custo_unitario) stored, market_lucro numeric(12,2) generated always as (market_quantidade * (market_preco_venda_unitario - market_preco_custo_unitario)) stored, market_vendido_em timestamptz not null default now(), market_criado_por uuid references auth.users(id));
create index if not exists market_produtos_nome_idx on public.market_produtos (market_mercado_id, market_nome);
create index if not exists market_produtos_categoria_idx on public.market_produtos (market_mercado_id, market_categoria);
create index if not exists market_vendas_data_idx on public.market_vendas (market_mercado_id, market_vendido_em);
alter table public.market_mercados enable row level security; alter table public.market_usuarios enable row level security; alter table public.market_produtos enable row level security; alter table public.market_vendas enable row level security;
create or replace function public.market_e_membro(p_mercado_id uuid) returns boolean language sql security definer set search_path = public as $$ select exists (select 1 from public.market_usuarios where market_mercado_id = p_mercado_id and market_usuario_id = auth.uid()) $$;
drop policy if exists market_usuarios_select on public.market_usuarios; create policy market_usuarios_select on public.market_usuarios for select using (market_usuario_id = auth.uid());
drop policy if exists market_produtos_select on public.market_produtos; create policy market_produtos_select on public.market_produtos for select using (public.market_e_membro(market_mercado_id));
drop policy if exists market_produtos_insert on public.market_produtos; create policy market_produtos_insert on public.market_produtos for insert with check (public.market_e_membro(market_mercado_id));
drop policy if exists market_produtos_update on public.market_produtos; create policy market_produtos_update on public.market_produtos for update using (public.market_e_membro(market_mercado_id));
drop policy if exists market_vendas_select on public.market_vendas; create policy market_vendas_select on public.market_vendas for select using (public.market_e_membro(market_mercado_id));
drop policy if exists market_vendas_insert on public.market_vendas; create policy market_vendas_insert on public.market_vendas for insert with check (public.market_e_membro(market_mercado_id));
create or replace function public.market_registrar_venda(p_market_produto_id uuid, p_market_quantidade integer) returns public.market_vendas language plpgsql security definer set search_path = public as $$ declare market_produto public.market_produtos; market_venda public.market_vendas; begin if p_market_quantidade <= 0 then raise exception 'market_quantidade_invalida'; end if; select * into market_produto from public.market_produtos where market_id = p_market_produto_id for update; if market_produto.market_id is null or not public.market_e_membro(market_produto.market_mercado_id) then raise exception 'market_produto_nao_autorizado'; end if; if market_produto.market_quantidade_estoque < p_market_quantidade then raise exception 'market_estoque_insuficiente'; end if; update public.market_produtos set market_quantidade_estoque = market_quantidade_estoque - p_market_quantidade where market_id = p_market_produto_id; insert into public.market_vendas (market_mercado_id, market_produto_id, market_quantidade, market_preco_custo_unitario, market_preco_venda_unitario, market_criado_por) values (market_produto.market_mercado_id, market_produto.market_id, p_market_quantidade, market_produto.market_preco_custo, market_produto.market_preco_venda, auth.uid()) returning * into market_venda; return market_venda; end $$;
